// ГЕЙМ ЧАСТЬ 5: ДВИЖЕНИЕ, ЗВУКИ И ИНТЕРФЕЙС КНОПОК
// ==========================================
let BOT_QUIZ_ACCURACY = 0.4;

function updateUI() {
    const activePlayer = players[currentTurn];
    const turnIndicator = document.getElementById("turn-indicator");
    const rollButton = document.getElementById("roll-button");
    
    turnIndicator.textContent = "Ходит: " + activePlayer.name;
    turnIndicator.style.color = activePlayer.color;
    
    if (!activePlayer.isBot && !isMoving) {
        rollButton.style.background = "#50fa7b";
        rollButton.style.color = "#0b3d1d";
        rollButton.style.boxShadow = "0 8px 22px rgba(80,250,123,0.5)";
        rollButton.style.cursor = "pointer";
    } else {
        rollButton.style.background = "#ff5555";
        rollButton.style.color = "#4d0f0f";
        rollButton.style.boxShadow = "0 8px 22px rgba(255,85,85,0.5)";
        rollButton.style.cursor = "not-allowed";
    }

    const listContainer = document.getElementById("bookmark-players-list");
    if (listContainer) {
        listContainer.innerHTML = "";
        players.forEach(p => {
            const row = document.createElement("div");
            row.className = "player-status-row";
            
            let badgeHTML = '<span class="badge-state badge-normal">—</span>';
            if (p.skipNextTurn) {
                badgeHTML = '<span class="badge-state badge-swamp">В болоте</span>';
            } else if (p.isJustGotBonus) {
                badgeHTML = '<span class="badge-state badge-gold">Доп. ход</span>';
            }
            
            row.innerHTML = `
                <div class="status-name-box">
                    <span class="status-color-dot" style="background: ${p.color}"></span>
                    <span style="font-weight: ${p.id === currentTurn ? 'bold' : 'normal'}">${p.name} (${p.score} б.)</span>
                </div>
                ${badgeHTML}
            `;
            listContainer.appendChild(row);
        });
    }
}

function playerTurn() {
    if (isMoving) return;
    if (players[currentTurn].isBot) return;
    executeTurn();
}

function executeTurn() {
    if (document.getElementById("win-modal").style.display === "block") return;
    
    isMoving = true;
    players[currentTurn].isJustGotBonus = false;
    updateUI(); 
    const activePlayer = players[currentTurn];
    
    if (activePlayer.skipNextTurn) {
        activePlayer.skipNextTurn = false;
        isMoving = false;
        nextTurn();
        return;
    }
    
    const diceRoll = Math.floor(Math.random() * 6) + 1;
    const videoEl = document.getElementById("dice-video");
    
    if (videoEl) {
        videoEl.src = "cubic_" + diceRoll + ".webm";
        videoEl.load();
        
        let hasAdvanced = false;
        const proceedOnce = function() {
            if (hasAdvanced) return;
            hasAdvanced = true;
            moveStepByStep(activePlayer, diceRoll, diceRoll, true);
        };

        videoEl.play().catch(err => {
            console.warn("Видео заблокировано браузером, шагаем сразу:", err);
            proceedOnce();
        });
        
        videoEl.onended = proceedOnce;
        // Защита от зависания хода, если видео кубика не смогло доиграть
        // (например, из-за медленной загрузки карты/сети)
        setTimeout(proceedOnce, 2500);
    } else {
        moveStepByStep(activePlayer, diceRoll, diceRoll, true);
    }
}

function moveStepByStep(player, stepsLeft, totalRoll, isFirstStep) {
    if (stepsLeft <= 0) {
        checkCellEffect(player);
        return;
    }
    
    const goesFork = Math.random() < 0.5;
    const nextCellId = getNextCellId(player.currentCell, goesFork);
    
    if (nextCellId === null) {
        player.score += 100;
        soundWin.play();
        showWinModal();
        return;
    }
    
    player.currentCell = nextCellId;
    drawGame();
    
    soundStep.currentTime = 0;
    soundStep.play().catch(() => {});
    
    let stepDelay = totalRoll >= 4 ? 700 : 500;
    setTimeout(() => { moveStepByStep(player, stepsLeft - 1, totalRoll, false); }, stepDelay);
}

function showWinModal() {
    isMoving = false;
    const winModal = document.getElementById("win-modal");
    const winnerNameEl = document.getElementById("winner-name");
    
    let highestScore = -1;
    let absoluteWinner = players;
    
    players.forEach(p => {
        if (p.score > highestScore) {
            highestScore = p.score;
            absoluteWinner = p;
        }
    });
    
    winnerNameEl.textContent = absoluteWinner.name + " (" + absoluteWinner.score + " б.)";
    winnerNameEl.style.background = absoluteWinner.color;
    
    winModal.style.display = "block";
}

function backToMenu() {
    document.getElementById("win-modal").style.display = "none";
    document.getElementById("game-interface").style.display = "none";
    document.getElementById("welcome-screen").style.display = "block";
    const videoEl = document.getElementById("dice-video");
    if (videoEl) videoEl.src = "";
    players = [];
    isMoving = false;
}

function checkCellEffect(player) {
    if (document.getElementById("win-modal").style.display === "block") return;

    const cell = boardRoute[player.currentCell];
    isExtraTurnEarned = false;
    
    if (cell) {
        if (cell.city) {
            player.lastOpenedCity = cell.city;
        }
        
        if (cell.type === "gold" || cell.isBonus) {
            player.isJustGotBonus = true;
            isExtraTurnEarned = true;
            soundGold.play().catch(() => {});
            
            if (!player.visitedGolds.includes(cell.city)) {
                player.visitedGolds.push(cell.city);
            }
            
            if (!player.isBot) {
                document.getElementById("gold-modal-text").textContent = cell.text;
                document.getElementById("gold-modal").style.display = "block";
                updateUI();
                return;
            }
        }
        if (cell.type === "swamp") { 
            player.skipNextTurn = true; 
        }
    }
    
    launchQuiz(player);
}

function toggleHintBookmark() {
    const panel = document.getElementById("hint-bookmark-panel");
    panel.classList.toggle("open");
}

function closeHintBookmark() {
    const panel = document.getElementById("hint-bookmark-panel");
    panel.classList.remove("open");
}

function launchQuiz(player) {
    if (allQuizQuestions.length === 0) {
        finishCellEffect();
        return;
    }

    let randomIndex;
    do {
        randomIndex = Math.floor(Math.random() * allQuizQuestions.length);
    } while (randomIndex === lastQuizIndex && allQuizQuestions.length > 1);
    lastQuizIndex = randomIndex;
    const qData = allQuizQuestions[randomIndex];
    const targetCity = qData.city;
    
    closeHintBookmark();
    const hintTextEl = document.getElementById("hint-bookmark-text");
    if (hintTextEl) {
        hintTextEl.textContent = qData.hint;
    }
    
    const hintTab = document.getElementById("hint-bookmark-tab");
    if (hintTab) {
        if (player.visitedGolds.includes(targetCity)) {
            hintTab.style.display = "none";
        } else {
            hintTab.style.display = "flex";
        }
    }
    
    if (!player.isBot) {
        document.getElementById("quiz-modal-question").textContent = `Текущая тема: ${targetCity}\n\n${qData.q}`;
        const container = document.getElementById("quiz-options-container");
        container.innerHTML = "";
        
        let shuffledIndices = Array.from({ length: qData.a.length }, (_, i) => i);
        shuffledIndices.sort(() => Math.random() - 0.5);
        
        shuffledIndices.forEach((origIndex) => {
            const optText = qData.a[origIndex];
            const btn = document.createElement("button");
            btn.className = "btn-quiz-opt";
            btn.textContent = optText;
            btn.onclick = function() {
                const allButtons = container.querySelectorAll(".btn-quiz-opt");
                allButtons.forEach(b => b.disabled = true);
                
                if (origIndex === qData.right) {
                    player.score += 10;
                    btn.style.background = "#50fa7b";
                    btn.style.color = "#111213";
                } else {
                    btn.style.background = "#ff5555";
                    allButtons.forEach((b, idx) => {
                        if (shuffledIndices[idx] === qData.right) {
                            b.style.background = "#50fa7b";
                            b.style.color = "#111213";
                        }
                    });
                }
                
                setTimeout(() => {
                    document.getElementById("quiz-modal").style.display = "none";
                    closeHintBookmark();
                    if (hintTab) { hintTab.style.display = "none"; }
                    finishCellEffect();
                }, 1500);
            };
            container.appendChild(btn);
        });
        document.getElementById("quiz-modal").style.display = "block";
    } else {
        if (hintTab) { hintTab.style.display = "none"; }
        const botAnswersCorrectly = Math.random() < BOT_QUIZ_ACCURACY;
        if (botAnswersCorrectly) {
            player.score += 10;
        }
        finishCellEffect();
    }
}

function closeGoldModal() {
    document.getElementById("gold-modal").style.display = "none";
    finishCellEffect();
}

function finishCellEffect() {
    if (document.getElementById("win-modal").style.display === "block") return;

    isMoving = false;
    const player = players[currentTurn];
    if (isExtraTurnEarned) {
        updateUI();
        if (player.isBot) { setTimeout(executeTurn, 1000); }
    } else {
        nextTurn();
    }
}

function nextTurn() {
    if (document.getElementById("win-modal").style.display === "block") return;

    currentTurn = (currentTurn + 1) % players.length;
    updateUI();
    if (players[currentTurn].isBot) { 
        setTimeout(() => { executeTurn(); }, 1000); 
    }
}

