function applySoundSettings() {
    [soundStep, soundGold, soundWin].forEach(function(a) {
        a.muted = !soundEnabled;
        a.volume = soundVolume;
    });
}

function syncSoundToggleUI() {
    const input = document.getElementById("sound-toggle-input");
    if (input) { input.checked = soundEnabled; }
    const row = document.getElementById("sound-volume-row");
    if (row) { row.style.display = soundEnabled ? "flex" : "none"; }
    const slider = document.getElementById("sound-volume-slider");
    if (slider) { slider.value = Math.round(soundVolume * 100); }
}

function toggleSound() {
    soundEnabled = !soundEnabled;
    try { localStorage.setItem("goldenRingSoundEnabled", soundEnabled ? "1" : "0"); } catch (e) {}
    applySoundSettings();
    syncSoundToggleUI();
}

function setSoundVolume(value) {
    soundVolume = Number(value) / 100;
    try { localStorage.setItem("goldenRingSoundVolume", String(soundVolume)); } catch (e) {}
    applySoundSettings();
}

function initSettings() {
    let savedTheme = null;
    try { savedTheme = localStorage.getItem("goldenRingTheme"); } catch (e) {}
    if (savedTheme === "light") { document.body.classList.add("light-theme"); }

    let savedEnergy = null;
    try { savedEnergy = localStorage.getItem("goldenRingEnergySaving"); } catch (e) {}
    if (savedEnergy === "1") {
        energySavingMode = true;
        document.body.classList.add("energy-saving");
    }

    let savedSoundEnabled = null;
    try { savedSoundEnabled = localStorage.getItem("goldenRingSoundEnabled"); } catch (e) {}
    if (savedSoundEnabled === "0") { soundEnabled = false; }

    let savedSoundVolume = null;
    try { savedSoundVolume = localStorage.getItem("goldenRingSoundVolume"); } catch (e) {}
    if (savedSoundVolume !== null) {
        const parsed = parseFloat(savedSoundVolume);
        if (!isNaN(parsed)) { soundVolume = parsed; }
    }

    applySoundSettings();
    syncThemeToggleUI();
    syncEnergyToggleUI();
    syncSoundToggleUI();
}

document.addEventListener("keydown", function(e) {
    if (e.key !== "Escape" && e.key !== "Esc") return;
    const creators = document.getElementById("creators-panel");
    const settings = document.getElementById("settings-panel");
    if (creators && creators.classList.contains("open")) {
        closeCreatorsPanel();
    } else if (settings && settings.classList.contains("open")) {
        closeSettingsPanel();
    }
});

initSettings();

// ==========================================
// ГЕЙМ ЧАСТЬ 7: ПЕРЕТАСКИВАНИЕ КНОПКИ НАСТРОЕК ПО УГЛАМ
// ==========================================
let gearDrag = { active: false, moved: false, offsetX: 0, offsetY: 0, startX: 0, startY: 0 };

function startGearDrag(e) {
    const btn = document.getElementById("settings-gear-btn");
    if (!btn) return;
    const point = e.touches ? e.touches[0] : e;
    const rect = btn.getBoundingClientRect();
    gearDrag.active = true;
    gearDrag.moved = false;
    gearDrag.startX = point.clientX;
    gearDrag.startY = point.clientY;
    gearDrag.offsetX = point.clientX - rect.left;
    gearDrag.offsetY = point.clientY - rect.top;
    btn.style.transition = "none";
    document.addEventListener("mousemove", moveGearDrag);
    document.addEventListener("touchmove", moveGearDrag, { passive: false });
    document.addEventListener("mouseup", endGearDrag);
    document.addEventListener("touchend", endGearDrag);
}

function moveGearDrag(e) {
    if (!gearDrag.active) return;
    e.preventDefault();
    const btn = document.getElementById("settings-gear-btn");
    const point = e.touches ? e.touches[0] : e;

    if (Math.abs(point.clientX - gearDrag.startX) > 5 || Math.abs(point.clientY - gearDrag.startY) > 5) {
        gearDrag.moved = true;
    }

    let left = point.clientX - gearDrag.offsetX;
    let top = point.clientY - gearDrag.offsetY;
    const maxLeft = window.innerWidth - btn.offsetWidth;
    const maxTop = window.innerHeight - btn.offsetHeight;
    left = Math.max(0, Math.min(left, maxLeft));
    top = Math.max(0, Math.min(top, maxTop));

    btn.style.right = "auto";
    btn.style.bottom = "auto";
    btn.style.left = left + "px";
    btn.style.top = top + "px";
}

function endGearDrag() {
    if (!gearDrag.active) return;
    gearDrag.active = false;
    document.removeEventListener("mousemove", moveGearDrag);
    document.removeEventListener("touchmove", moveGearDrag);
    document.removeEventListener("mouseup", endGearDrag);
    document.removeEventListener("touchend", endGearDrag);

    snapGearToNearestCorner();

    if (!gearDrag.moved) {
        openSettingsPanel();
    }
}

function snapGearToNearestCorner() {
    const btn = document.getElementById("settings-gear-btn");
    if (!btn) return;
    const rect = btn.getBoundingClientRect();
    const centerX = rect.left + rect.width / 2;
    const centerY = rect.top + rect.height / 2;
    const isRight = centerX > window.innerWidth / 2;
    const isBottom = centerY > window.innerHeight / 2;
    applyGearCorner((isBottom ? "bottom" : "top") + "-" + (isRight ? "right" : "left"), true);
}

function applyGearCorner(corner, animate) {
    const btn = document.getElementById("settings-gear-btn");
    if (!btn) return;
    const margin = "20px";
    const isBottom = corner.indexOf("bottom") === 0;
    const isRight = corner.indexOf("right") !== -1;

    btn.style.transition = (animate && !energySavingMode) ? "left 0.3s ease, right 0.3s ease, top 0.3s ease, bottom 0.3s ease" : "none";
    btn.style.left = isRight ? "auto" : margin;
    btn.style.right = isRight ? margin : "auto";
    btn.style.top = isBottom ? "auto" : margin;
    btn.style.bottom = isBottom ? margin : "auto";

    try { localStorage.setItem("goldenRingGearCorner", corner); } catch (e) {}
}

function initGearDrag() {
    const btn = document.getElementById("settings-gear-btn");
    if (!btn) return;

    let savedCorner = null;
    try { savedCorner = localStorage.getItem("goldenRingGearCorner"); } catch (e) {}
    if (savedCorner) { applyGearCorner(savedCorner, false); }

    btn.addEventListener("mousedown", startGearDrag);
    btn.addEventListener("touchstart", startGearDrag, { passive: false });
}

initGearDrag();
